253	    /**
254	     * Rejects saving {@code owner} when it carries a postcode that is out of range for its city's
255	     * region. The postcode is optional: a {@code null} postcode is left untouched. When present it
256	     * is assumed to already be four digits (enforced by request validation); if the owner's city has
257	     * a known region (see {@link Region}), the postcode must fall within that region's range
258	     * ({@link Region#postcodeRange(String)}). A city with no known region accepts any 4-digit
259	     * postcode.
260	     *
261	     * @throws InvalidPostcodeException if the postcode is out of range for the city's region
262	     */
263	    private void assertPostcodeValid(Owner owner) {
264	        String postcode = owner.getPostcode();
265	        if (postcode == null) {
266	            return;
267	        }
268	        String region = Region.forCity(owner.getCity());
269	        int[] range = region == null ? null : Region.postcodeRange(region);
270	        if (range == null) {
271	            return;
272	        }
273	        int value = Integer.parseInt(postcode);
274	        if (value < range[0] || value > range[1]) {
275	            throw new InvalidPostcodeException(postcode, owner.getCity(), region);
276	        }
277	    }
278	
279	    /**
280	     * Rejects saving {@code owner} when it carries a {@code registrationDate} later than the current
281	     * server date. The registration date is optional: a {@code null} date is left untouched (it is
282	     * defaulted to today by {@link #saveOwner(Owner)}). A registration cannot be dated in the future.
283	     *
284	     * @throws FutureRegistrationDateException if the supplied registration date is after today
285	     */
286	    private void assertRegistrationDateNotFuture(Owner owner) {
287	        LocalDate registrationDate = owner.getRegistrationDate();
288	        if (registrationDate == null) {
289	            return;
290	        }
291	        LocalDate today = LocalDate.now();
292	        if (registrationDate.isAfter(today)) {
293	            throw new FutureRegistrationDateException(registrationDate, today);
294	        }
295	    }
