297	    /** Email domains rejected as disposable/throwaway addresses. */
298	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS = Set.of(
299	        "mailinator.com", "tempmail.com", "guerrillamail.com");
300	
301	    /**
302	     * Rejects saving {@code owner} when its email's domain is on the disposable-domain blocklist
303	     * ({@link #DISPOSABLE_EMAIL_DOMAINS}). The email is optional: a {@code null} email is left
304	     * untouched. The comparison is case-insensitive on the part after the last {@code '@'}; the
305	     * email has already been lower-cased by {@link #saveOwner(Owner)} before this runs.
306	     *
307	     * @throws DisposableEmailDomainException if the email domain is blocklisted
308	     */
309	    private void assertEmailDomainAllowed(Owner owner) {
310	        String email = owner.getEmail();
311	        if (email == null) {
312	            return;
313	        }
314	        int at = email.lastIndexOf('@');
315	        if (at < 0) {
316	            return;
317	        }
318	        String domain = email.substring(at + 1).toLowerCase(Locale.ROOT);
319	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
320	            throw new DisposableEmailDomainException(domain);
321	        }
322	    }
