420	    /** Maximum number of owners permitted in a single city. */
421	    private static final long CITY_OWNER_LIMIT = 50L;
422	
423	    /**
424	     * Rejects creating {@code owner} when its city already contains {@link #CITY_OWNER_LIMIT} or
425	     * more owners, so no city can grow beyond the capacity limit.
426	     *
427	     * @throws CityOwnerLimitException if the owner's city is already at capacity
428	     */
429	    private void assertCityCapacity(Owner owner) {
430	        if (owner.getCity() == null) {
431	            return;
432	        }
433	        if (countOwnersInCity(owner.getCity()) >= CITY_OWNER_LIMIT) {
434	            throw new CityOwnerLimitException(owner.getCity(), CITY_OWNER_LIMIT);
435	        }
436	    }
437	
438	    /** Fixed public holidays that the business-day roll skips. */
439	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
440	            LocalDate.parse("2026-01-01"), LocalDate.parse("2026-01-26"),
441	            LocalDate.parse("2026-04-25"), LocalDate.parse("2026-12-25"),
442	            LocalDate.parse("2026-12-28"));
443	
444	    /**
445	     * Rolls {@code date} forward to the next business day. A business day is Monday to Friday that is
446	     * not a listed public holiday; Saturdays, Sundays and public holidays are skipped by advancing
447	     * one day at a time until a business day is reached. Business days are returned unchanged.
448	     */
449	    private static LocalDate rollToBusinessDay(LocalDate date) {
450	        while (isWeekend(date) || PUBLIC_HOLIDAYS.contains(date)) {
451	            date = date.plusDays(1);
452	        }
453	        return date;
454	    }
455	
456	    private static boolean isWeekend(LocalDate date) {
457	        switch (date.getDayOfWeek()) {
458	            case SATURDAY:
459	            case SUNDAY:
460	                return true;
461	            default:
462	                return false;
463	        }
464	    }
