483	    /**
484	     * Rejects creating {@code owner} when its {@code registrationDate} (defaulted to today for a new
485	     * owner) already has {@link #DAILY_OWNER_LIMIT} or more owners registered, so no more than that
486	     * many owners can be created on any single day.
487	     *
488	     * @throws DailyOwnerLimitException if the owner's registration day is already at capacity
489	     */
490	    private void assertDailyCapacity(Owner owner) {
491	        LocalDate date = owner.getRegistrationDate();
492	        if (date == null) {
493	            return;
494	        }
495	        if (countOwnersRegisteredOn(date) >= DAILY_OWNER_LIMIT) {
496	            throw new DailyOwnerLimitException(date, DAILY_OWNER_LIMIT);
497	        }
498	    }
