506	    private long countOwnersInCity(String city) {
507	        String normalized = normalizeHouseholdValue(city);
508	        return ownerRepository.findAll().stream()
509	                .filter(existing -> normalized.equals(normalizeHouseholdValue(existing.getCity())))
510	                .count();
511	    }
512	
513	    /**
514	     * Counts the existing owners that share both {@code firstName} and {@code lastName} with the
515	     * given new {@code owner}, compared case-insensitively (with incidental whitespace collapsed).
516	     * The owner being created is not itself persisted yet, so the result is the number of namesakes
517	     * that already existed before this create.
518	     */
519	    private int countNamesakes(Owner owner) {
520	        String firstName = normalizeHouseholdValue(owner.getFirstName());
521	        String lastName = normalizeHouseholdValue(owner.getLastName());
522	        int count = 0;
523	        for (Owner existing : ownerRepository.findAll()) {
524	            if (!existing.getId().equals(owner.getId())
525	                    && firstName.equals(normalizeHouseholdValue(existing.getFirstName()))
526	                    && lastName.equals(normalizeHouseholdValue(existing.getLastName()))) {
527	                count++;
528	            }
529	        }
530	        return count;
531	    }
532	
533	    private static String normalizeEmail(String email) {
534	        return email == null ? null : email.toLowerCase(Locale.ROOT);
535	    }
536	
537	    /**
538	     * Normalizes whichever address fields {@code owner} supplied and derives the effective flat
539	     * {@code address} from them. The structured form is preferred: when a non-blank
540	     * {@code addressLine1} is present, {@code address} is set to the normalized {@code addressLine1},
541	     * with a single space and the normalized {@code addressLine2} appended when {@code addressLine2}
542	     * is present. Otherwise the flat {@code address} is normalized in place (backward-compatible). The
543	     * structured fields are also stored in their normalized form. Because everything downstream reads
544	     * {@link Owner#getAddress()}, the household hash, postcode validation and locality all see the
545	     * structured value when present and fall back to the flat address otherwise.
546	     */
547	    private static void applyAddress(Owner owner) {
548	        String line1 = normalizeAddress(owner.getAddressLine1());
549	        String line2 = normalizeAddress(owner.getAddressLine2());
550	        owner.setAddressLine1(line1);
551	        owner.setAddressLine2(line2);
552	        if (line1 != null && !line1.isEmpty()) {
553	            String composed = (line2 != null && !line2.isEmpty()) ? line1 + " " + line2 : line1;
554	            owner.setAddress(composed);
555	        } else if (owner.getAddress() != null) {
556	            owner.setAddress(normalizeAddress(owner.getAddress()));
557	        }
558	    }
559	
560	    /** Common street-type abbreviations expanded during address normalization. */
561	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
562	        "ST", "STREET",
563	        "RD", "ROAD",
564	        "AVE", "AVENUE");
565	
566	    /**
567	     * Canonicalizes a postal address: trims and collapses runs of whitespace into a single space,
568	     * upper-cases, and expands common street-type abbreviations (ST->STREET, RD->ROAD, AVE->AVENUE)
569	     * as whole words. Returns {@code null} for a {@code null} input and an empty string when the
570	     * address is blank once whitespace is stripped, so the required-field check sees the normalized
571	     * form.
572	     */
573	    private static String normalizeAddress(String address) {
574	        if (address == null) {
575	            return null;
576	        }
577	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
578	        if (collapsed.isEmpty()) {
579	            return "";
580	        }
581	        String[] tokens = collapsed.split(" ");
582	        StringBuilder sb = new StringBuilder(collapsed.length());
583	        for (int i = 0; i < tokens.length; i++) {
584	            if (i > 0) {
585	                sb.append(' ');
586	            }
587	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
588	        }
589	        return sb.toString();
590	    }
591	
592	    private static String normalizeTelephone(String telephone) {
593	        return telephone == null ? null : E164Telephone.toE164(telephone);
594	    }
595	
596	    /**
597	     * Rejects saving {@code owner} when its whole {@link Owner#getIdentityKey() identity key} equals
598	     * that of another owner. This single check consolidates the former separate telephone, email and
599	     * household duplicate rules: because the normalized telephone is part of the key, two members of
600	     * the same household (same {@code householdId}) with different telephones have different keys and
601	     * are both allowed — only an exact full-key match is a duplicate.
602	     *
603	     * @throws DuplicateIdentityException if another owner already has the same identity key
604	     */
605	    private void assertIdentityUnique(Owner owner) {
606	        String identityKey = owner.getIdentityKey();
607	        for (Owner existing : ownerRepository.findAll()) {
608	            if (!existing.getId().equals(owner.getId()) && !existing.isDeleted()
609	                    && identityKey.equals(existing.getIdentityKey())) {
610	                throw new DuplicateIdentityException(identityKey);
611	            }
612	        }
613	    }
614	
615	    /**
616	     * Assigns {@code owner} its deterministic {@code householdId}: the first 12 upper-case hex
617	     * characters of the SHA-256 digest over {@code normalizedLastName + '|' + postcode}, so all
618	     * owners that share a normalized {@code lastName} and {@code postcode} automatically share the
619	     * same household. Left {@code null} when either the lastName or the postcode is absent, since a
620	     * household is keyed on both.
621	     */
622	    private void assignHouseholdId(Owner owner) {
623	        String lastName = normalizeHouseholdValue(owner.getLastName());
624	        String postcode = owner.getPostcode();
625	        if (lastName.isEmpty() || postcode == null || postcode.isBlank()) {
626	            owner.setHouseholdId(null);
627	            return;
628	        }
629	        owner.setHouseholdId(generateHouseholdId(lastName, postcode));
630	    }
631	
632	    /**
633	     * Captures the membership-level ceiling for a newly created {@code owner}: its
634	     * {@link Owner#getMembershipLevel() membership level} may not exceed one above the highest level
635	     * among the household members (owners sharing its {@code householdId}) that already exist. When
636	     * the owner belongs to no household, or no existing member shares it, no cap applies and the
637	     * level is left uncapped. Each existing member's household size is stamped via
638	     * {@link #populateHouseholdSizes(Collection)} first so its level reflects the household-size
639	     * membership points.
640	     *
641	     * @see Owner#getMembershipLevelCap()
642	     */
643	    private void applyMembershipLevelCap(Owner owner) {
644	        owner.setMembershipLevelCap(null);
645	        String householdId = owner.getHouseholdId();
646	        if (householdId == null || householdId.isBlank()) {
647	            return;
648	        }
649	        List<Owner> members = new ArrayList<>();
650	        for (Owner existing : ownerRepository.findAll()) {
651	            if (!existing.getId().equals(owner.getId()) && !existing.isDeleted()
652	                    && householdId.equals(existing.getHouseholdId())) {
653	                members.add(existing);
654	            }
655	        }
656	        if (members.isEmpty()) {
657	            return;
658	        }
659	        populateHouseholdSizes(members);
660	        int maxLevel = 0;
661	        for (Owner member : members) {
662	            maxLevel = Math.max(maxLevel, member.getMembershipLevel());
663	        }
664	        owner.setMembershipLevelCap(maxLevel + 1);
665	    }
666	
667	    /**
668	     * Stamps {@code owner} with the number of owners sharing its {@code householdId} (see {@link
669	     * Owner#getHouseholdSize()}), so presentation code can derive the membership tier without
670	     * reaching into the data store. A {@code null} owner or one without a household id is left at
671	     * size 0.
672	     */
673	    private void populateHouseholdSize(Owner owner) {
674	        if (owner == null) {
675	            return;
676	        }
677	        String householdId = owner.getHouseholdId();
678	        if (householdId == null || householdId.isBlank()) {
679	            owner.setHouseholdSize(0);
680	            return;
681	        }
682	        int count = 0;
683	        for (Owner existing : ownerRepository.findAll()) {
684	            if (householdId.equals(existing.getHouseholdId())) {
685	                count++;
686	            }
687	        }
688	        owner.setHouseholdSize(count);
689	    }
690	
691	    /**
692	     * Stamps every owner in {@code owners} with its household size in a single pass over the data
693	     * store, so a list/page of owners is counted without a per-owner query.
694	     *
695	     * @see #populateHouseholdSize(Owner)
696	     */
697	    private void populateHouseholdSizes(Collection<Owner> owners) {
698	        if (owners.isEmpty()) {
699	            return;
700	        }
701	        Map<String, Integer> sizes = new HashMap<>();
702	        for (Owner existing : ownerRepository.findAll()) {
703	            String householdId = existing.getHouseholdId();
704	            if (householdId != null && !householdId.isBlank()) {
705	                sizes.merge(householdId, 1, Integer::sum);
706	            }
707	        }
708	        for (Owner owner : owners) {
709	            String householdId = owner.getHouseholdId();
710	            owner.setHouseholdSize(householdId == null ? 0 : sizes.getOrDefault(householdId, 0));
711	        }
712	    }
713	
714	    /**
715	     * Derives the deterministic {@code householdId} from the normalized {@code lastName} and
716	     * {@code postcode}: the first 12 upper-case hex characters of SHA-256 over
717	     * {@code lastName + '|' + postcode}, so all owners in the same household share the same
718	     * identifier.
719	     */
720	    private static String generateHouseholdId(String lastName, String postcode) {
721	        return sha256UpperHex(lastName + "|" + postcode, 12);
722	    }
723	
724	    /**
725	     * Normalizes a household comparison value by trimming, collapsing runs of whitespace into a
726	     * single space and lower-casing, so comparisons ignore case and incidental whitespace.
727	     */
728	    private static String normalizeHouseholdValue(String value) {
729	        if (value == null) {
730	            return "";
731	        }
732	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
733	    }
734	
735	    @Override
736	    @Transactional(readOnly = true)
737	    public Collection<Owner> findOwnerByLastName(String lastName) throws DataAccessException {
738	        Collection<Owner> owners = ownerRepository.findByLastName(lastName);
739	        populateHouseholdSizes(owners);
740	        return owners;
741	    }
742	
743	    @Override
744	    @Transactional(readOnly = true)
745	    public Collection<Visit> findVisitsByPetId(int petId) {
746	        return visitRepository.findByPetId(petId);
747	    }
748	
749	    @Override
750	    @Transactional(readOnly = true)
751	    public List<Specialty> findSpecialtiesByNameIn(Set<String> names) {
752	        return findEntityById(() -> specialtyRepository.findSpecialtiesByNameIn(names));
753	    }
754	
755	    private <T> T findEntityById(Supplier<T> supplier) {
756	        try {
757	            return supplier.get();
758	        } catch (ObjectRetrievalFailureException | EmptyResultDataAccessException e) {
759	            // Just ignore not found exceptions for Jdbc/Jpa realization
760	            return null;
761	        }
762	    }
763	
764	}
