313	    /** The household size at or above which an owner earns the household membership points. */
314	    public static final int MEMBERSHIP_HOUSEHOLD_SIZE = 3;
315	
316	    /** The month (1 July) on which the fiscal year begins. */
317	    public static final int FISCAL_YEAR_START_MONTH = 7;
318	
319	    /**
320	     * The number of elapsed fiscal years at or above which an owner earns the tenure membership
321	     * points.
322	     */
323	    public static final long MEMBERSHIP_TENURE_FISCAL_YEARS = 1;
324	
325	    /**
326	     * The fiscal year (as a full four-digit number) that {@code date} falls in, where the fiscal
327	     * year begins on 1 July and is labelled by the calendar year in which it ends: a date on or
328	     * after 1 July belongs to the next calendar year's fiscal year.
329	     */
330	    public static int fiscalYearOf(LocalDate date) {
331	        return date.getMonthValue() >= FISCAL_YEAR_START_MONTH ? date.getYear() + 1 : date.getYear();
332	    }
333	
334	    /**
335	     * The fiscal year of the owner's (business-day-adjusted) {@code registrationDate}, formatted
336	     * {@code 'FY<YY>'} where YY is the last two digits of the fiscal year (see
337	     * {@link #fiscalYearOf(LocalDate)}). Null when no registration date is set.
338	     */
339	    public String getFiscalYear() {
340	        if (this.registrationDate == null) {
341	            return null;
342	        }
343	        return String.format("FY%02d", fiscalYearOf(this.registrationDate) % 100);
344	    }
345	
346	    /**
347	     * The owner's membership points, computed from stored fields: they start at 0, gain 2 when an
348	     * email is present, gain 1 when {@code namesakeCount} is 0, gain 2 for a household of
349	     * {@value #MEMBERSHIP_HOUSEHOLD_SIZE} or more (see {@link #getHouseholdSize()}), and gain 3 when
350	     * the owner's tenure (fiscal years elapsed since its {@code registrationDate}) is at least
351	     * {@value #MEMBERSHIP_TENURE_FISCAL_YEARS}.
352	     */
353	    public int getMembershipPoints() {
354	        int points = 0;
355	        if (this.email != null && !this.email.isEmpty()) {
356	            points += 2;
357	        }
358	        if (this.namesakeCount != null && this.namesakeCount == 0) {
359	            points += 1;
360	        }
361	        if (this.householdSize >= MEMBERSHIP_HOUSEHOLD_SIZE) {
362	            points += 2;
363	        }
364	        if (this.registrationDate != null
365	                && (fiscalYearOf(LocalDate.now()) - fiscalYearOf(this.registrationDate))
366	                        >= MEMBERSHIP_TENURE_FISCAL_YEARS) {
367	            points += 3;
368	        }
369	        return points;
370	    }
371	
372	    /**
373	     * The owner's numeric membership level, mapped from {@link #getMembershipPoints()}: 1 for 0-1
374	     * points, 2 for 2-3 points, 3 for 4-5 points, and 4 for 6 or more points, then capped by the
375	     * {@link #getMembershipLevelCap() membership level cap} when one was captured at creation time.
376	     */
377	    public int getMembershipLevel() {
378	        int level = computeMembershipLevel();
379	        if (this.membershipLevelCap != null && level > this.membershipLevelCap) {
380	            return this.membershipLevelCap;
381	        }
382	        return level;
383	    }
384	
385	    /**
386	     * The uncapped membership level derived purely from {@link #getMembershipPoints()}: 1 for 0-1
387	     * points, 2 for 2-3 points, 3 for 4-5 points, and 4 for 6 or more points.
388	     */
389	    private int computeMembershipLevel() {
390	        int points = getMembershipPoints();
391	        if (points >= 6) {
392	            return 4;
393	        }
394	        if (points >= 4) {
395	            return 3;
396	        }
397	        if (points >= 2) {
398	            return 2;
399	        }
400	        return 1;
401	    }
402	
403	    public Integer getMembershipLevelCap() {
404	        return this.membershipLevelCap;
405	    }
406	
407	    public void setMembershipLevelCap(Integer membershipLevelCap) {
408	        this.membershipLevelCap = membershipLevelCap;
409	    }
410	
411	    /**
412	     * The derived identity key used to detect duplicate owners: the (already normalized) telephone,
413	     * the email or empty, and the {@code householdId} or empty, joined with {@code '|'}. This single
414	     * key consolidates the former separate telephone, email and household duplicate rules — two
415	     * owners are duplicates only when their whole identity keys are equal. Because the telephone is
416	     * part of the key, two members of the same household (same {@code householdId}) with different
417	     * telephones have different keys and are both allowed.
418	     */
419	    public String getIdentityKey() {
420	        String tel = this.telephone == null ? "" : this.telephone;
421	        String mail = this.email == null ? "" : this.email;
422	        String household = this.householdId == null ? "" : this.householdId;
423	        return tel + "|" + mail + "|" + household;
424	    }
425	
426	    /**
427	     * A single Luhn check digit (0-9) computed over the digits contained in {@code customerCode},
428	     * or null when the {@code customerCode} has not been assigned.
429	     */
430	    public Integer getCheckDigit() {
431	        if (this.customerCode == null) {
432	            return null;
433	        }
434	        int sum = 0;
435	        boolean dbl = true;
436	        for (int i = this.customerCode.length() - 1; i >= 0; i--) {
437	            char c = this.customerCode.charAt(i);
438	            if (c < '0' || c > '9') {
439	                continue;
440	            }
441	            int d = c - '0';
442	            if (dbl) {
443	                d *= 2;
444	                if (d > 9) {
445	                    d -= 9;
446	                }
447	            }
448	            sum += d;
449	            dbl = !dbl;
450	        }
451	        return (10 - (sum % 10)) % 10;
452	    }
453	
454	    /**
455	     * The owner's membership number formatted {@code '<customerCode>-M<YY>'} where YY is the last
456	     * two digits of the fiscal year of the {@code registrationDate} (see
457	     * {@link #fiscalYearOf(LocalDate)}), or null when either the {@code customerCode} or the
458	     * {@code registrationDate} is not set.
459	     */
460	    public String getMembershipNumber() {
461	        if (this.customerCode == null || this.registrationDate == null) {
462	            return null;
463	        }
464	        String yy = String.format("%02d", fiscalYearOf(this.registrationDate) % 100);
465	        return this.customerCode + "-M" + yy;
466	    }
